import { useEffect, useMemo, useState } from "react";
import { Link, useLocation, useNavigate, useParams } from "react-router-dom";
import { api } from "../api/client";
import { ActionMenu } from "../components/ActionMenu";
import { MachineKnowledgeView } from "../features/postRecords/MachineKnowledgeView";
import type { CustomLogicItem, GPostDraft, MachineKnowledgeFact, MachineProfile, OFGSetting,
  GPostDiagnostic, PostOpenQuestion, PostRecordSummary, PostStandardApplication, PostValidationRecord,
  SiteStandard, SourceDocument, ValidationFinding, ValidationPolicy } from "../types";

const researchToolsEnabled = import.meta.env.VITE_ENABLE_RESEARCH_TOOLS === "true";

const overallLabels: Record<string, string> = {
  setup: "Setup", building: "Building", needs_information: "Needs Information",
  ready_for_engineering_review: "Ready for Engineering Review", under_validation: "Under Validation",
  rnd_validated: "R&D Validated", archived: "Archived",
};
const factStatuses = ["confirmed", "needs_review", "unknown", "conflicting", "not_applicable"];
const ofgStatuses = ["unmapped", "mapped", "needs_review", "needs_information", "reviewed", "not_applicable", "custom_logic_required"];
const pretty = (value?: string) => (value || "unknown").replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
const ofgStatus = (value: string) => value === "conflicting" ? "Needs Review" : pretty(value);
const ofgCategory = (value: string) => value;
const relevanceLabel = (value: string) => ({ required_for_post: "Required for this Post", applicable: "Applicable", optional: "Optional", not_applicable: "Not Applicable", advanced: "Advanced" }[value] || pretty(value));
const pathLabel = (value: string) => ({ verified_from_reference: "Verified From OFG Reference", site_verification_needed: "Site Verification Needed", not_verified: "Not Verified" }[value] || pretty(value));
const displayValue = (value: unknown) => value == null || value === "" ? "—" : Array.isArray(value) ? value.join(" – ") : typeof value === "object" ? JSON.stringify(value) : String(value);

export function PostRecordWorkspacePage() {
  const id = Number(useParams().draftId); const location = useLocation(); const navigate = useNavigate();
  const parts = location.pathname.replace(new RegExp(`^/gpost/${id}/?`), "").split("/").filter(Boolean);
  const routeView = parts[0] || "overview";
  const view = routeView === "site-standards" ? "ofg-configuration" : routeView === "review-validation" ? "review-export" : ["versions", "sources"].includes(routeView) ? "history-sources" : routeView;
  const detailId = ["machine-knowledge", "ofg-configuration"].includes(routeView) ? Number(parts[1]) || null : null;
  const [draft, setDraft] = useState<GPostDraft | null>(null); const [machine, setMachine] = useState<MachineProfile | null>(null);
  const [summary, setSummary] = useState<PostRecordSummary | null>(null); const [facts, setFacts] = useState<MachineKnowledgeFact[]>([]);
  const [settings, setSettings] = useState<OFGSetting[]>([]); const [standards, setStandards] = useState<SiteStandard[]>([]);
  const [applications, setApplications] = useState<PostStandardApplication[]>([]); const [logic, setLogic] = useState<CustomLogicItem[]>([]);
  const [questions, setQuestions] = useState<PostOpenQuestion[]>([]); const [validations, setValidations] = useState<PostValidationRecord[]>([]);
  const [findings, setFindings] = useState<ValidationFinding[]>([]); const [diagnostics, setDiagnostics] = useState<GPostDiagnostic[]>([]);
  const [validationPolicy, setValidationPolicy] = useState<ValidationPolicy | null>(null);
  const [versions, setVersions] = useState<GPostDraft[]>([]); const [documents, setDocuments] = useState<SourceDocument[]>([]);
  const [search, setSearch] = useState(""); const [filter, setFilter] = useState("all"); const [category, setCategory] = useState("all"); const [customOnly, setCustomOnly] = useState(false);
  const [relevance, setRelevance] = useState("all"); const [showAdvanced, setShowAdvanced] = useState(false);
  const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const [exportOpen, setExportOpen] = useState(false);

  async function load() {
    try {
      const nextDraft = await api.getGPostDraft(id); const profiles = await api.listProfiles();
      const [nextSummary, nextFacts, nextSettings, allStandards, nextApplications, nextLogic, nextQuestions, nextValidations, nextVersions, nextDocs,
        nextFindings, nextDiagnostics, nextPolicy] = await Promise.all([
        api.getPostRecordSummary(id), api.listMachineKnowledge(id), api.listOFGSettings(id, true), api.listSiteStandards(),
        api.listPostStandards(id), api.listCustomLogic(id), api.listPostQuestions(id), api.listPostValidations(id),
        api.listGPostVersions(id), api.listDocuments(nextDraft.machine_profile_id),
        api.listValidationFindings(id), api.listGPostDiagnostics(id), api.getValidationPolicy(id),
      ]);
      setDraft(nextDraft); setMachine(profiles.find((item) => item.id === nextDraft.machine_profile_id) ?? null);
      setSummary(nextSummary); setFacts(nextFacts); setSettings(nextSettings); setStandards(allStandards);
      setApplications(nextApplications); setLogic(nextLogic); setQuestions(nextQuestions); setValidations(nextValidations);
      setVersions(nextVersions); setDocuments(nextDocs);
      setFindings(nextFindings); setDiagnostics(nextDiagnostics); setValidationPolicy(nextPolicy);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to load Post Record."); }
  }
  useEffect(() => { void load(); }, [id]);
  async function act(work: () => Promise<unknown>) { setBusy(true); setError(""); try { await work(); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Action failed."); } finally { setBusy(false); } }
  async function createVersion() { setBusy(true); try { const created = await api.createGPostVersion(id); navigate(`/gpost/${created.id}/history-sources`); } catch (cause) { setError(cause instanceof Error ? cause.message : "Version creation failed."); } finally { setBusy(false); } }
  if (!draft || !machine || !summary) return <section className="page">{error ? <p className="form-error">{error}</p> : <p>Loading Post Record…</p>}</section>;
  const base = `/gpost/${id}`; const selectedFact = facts.find((item) => item.id === detailId); const selectedSetting = settings.find((item) => item.id === detailId);
  const status = overallLabels[summary.status] ?? pretty(summary.status); const nextPath = summary.next_action.path === "review-validation" ? "review-export" : summary.next_action.path === "site-standards" ? "ofg-configuration" : summary.next_action.path;
  const visibleSettings = settings.filter((item) => item.is_applicable !== false
    ? (showAdvanced || item.relevance_class !== "advanced")
    : (showAdvanced && item.relevance_class === "advanced"));
  return <section className="page post-record-workspace">
    <header className="post-record-header"><div><Link to="/gpost">← Post Records</Link><span className="eyebrow">Post Record</span><h1>{draft.name}</h1><p>{machine.machine_type.replaceAll("_", " ")} · {machine.controller_model || machine.controller_name}</p></div><div className="workspace-actions"><span className={`post-status ${summary.status}`}>{status}</span><Link className="button primary" to={`${base}/${nextPath}`}>{summary.next_action.label}</Link><ActionMenu label="More" items={[
      { label: "Create Version", onSelect: () => void createVersion() },
      { label: "Export Development Package", onSelect: () => setExportOpen(true) },
      { label: "Rename", onSelect: () => { const name = window.prompt("Post Record name", draft.name); if (name?.trim()) void act(() => api.updateGPostDraft(id, { name: name.trim() })); } },
      { label: "Archive", onSelect: () => void act(() => api.archiveGPostDraft(id)) },
      { label: "Delete", danger: true, divider: true, onSelect: () => { if (window.confirm("Delete this Post Record? Version retention may require archiving instead.")) void act(() => api.deleteGPostDraft(id)); } },
    ]} /></div></header>
    <aside className="compact-governance"><strong>ENGINEERING DEVELOPMENT RECORD</strong><span>AI assists explicit development tasks only. CL/NCL, CAD/part geometry, toolpaths, production NC, and part-specific diagnostics are prohibited from AI context.</span></aside>
    <nav className="post-record-tabs" aria-label="Post Record workflow">
      <Link className={view === "overview" ? "active" : ""} to={base}>Overview</Link>
      <Link title="Reviewed machine/controller facts extracted from manuals or entered by an engineer." className={view === "machine-knowledge" ? "active" : ""} to={`${base}/machine-knowledge`}>Machine Knowledge</Link>
      <Link title="A checklist of reviewed values/settings intended to guide configuration in G-POST Option File Generator." className={view === "ofg-configuration" ? "active" : ""} to={`${base}/ofg-configuration`}>OFG Configuration</Link>
      <Link title="Machine/site-specific behavior that may require post customization beyond the standard OFG checklist." className={view === "custom-logic" ? "active" : ""} to={`${base}/custom-logic`}>Custom Logic</Link>
      <Link className={view === "review-export" ? "active" : ""} to={`${base}/review-export`}>Review &amp; Export</Link>
      <Link className={view === "history-sources" ? "active" : ""} to={`${base}/history-sources`}>History &amp; Sources</Link>
    </nav>
    <details className="workspace-technical-details"><summary>Technical Details</summary><Link to={`${base}/advanced/technical`}>Configuration and audit details</Link>{researchToolsEnabled && <Link to="/research-tools">Research Tools</Link>}</details>
    {error && <p className="form-error" role="alert">{error}</p>}

    {view === "overview" && <Overview base={base} draft={draft} machine={machine} summary={summary} documents={documents} />}
    {view === "machine-knowledge" && !selectedFact && <MachineKnowledgeView facts={facts} questions={questions} machineId={machine.id} base={base} onReview={(fact, payload) => void act(() => api.updateMachineKnowledge(id, fact.id, payload))} />}
    {view === "machine-knowledge" && selectedFact && <MachineFactDetail fact={selectedFact} back={`${base}/machine-knowledge`} save={(payload) => act(() => api.updateMachineKnowledge(id, selectedFact.id, payload))} machineId={machine.id} />}

    {view === "ofg-configuration" && !selectedSetting && <EngineeringTable title={<>OFG Configuration <span className="concept-help" title="A machine-specific checklist grounded in the collected OFG reference.">ⓘ</span></>} description="This checklist represents the Option File Generator settings believed relevant to this machine and post. Values should be reviewed before they are entered into the official G-POST environment." search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} category={category} setCategory={setCategory} statuses={ofgStatuses} categories={[...new Set(visibleSettings.map((item) => item.category))]} primaryAction={visibleSettings.find((item) => !["reviewed", "not_applicable"].includes(item.status)) ? <Link className="button primary" to={`${base}/ofg-configuration/${visibleSettings.find((item) => !["reviewed", "not_applicable"].includes(item.status))!.id}`}>Review Next Setting</Link> : undefined} extraFilter={<><label>Relevance<select value={relevance} onChange={(event) => setRelevance(event.target.value)}><option value="all">All relevance</option><option value="required_for_post">Required for this Post</option><option value="applicable">Applicable</option><option value="optional">Optional</option><option value="not_applicable">Not Applicable</option><option value="advanced">Advanced</option></select></label><label>Custom Logic<select value={customOnly ? "yes" : "all"} onChange={(event) => setCustomOnly(event.target.value === "yes")}><option value="all">All</option><option value="yes">Required</option></select></label><label className="advanced-disclosure"><input type="checkbox" checked={showAdvanced} onChange={(event) => setShowAdvanced(event.target.checked)} /> Show Advanced settings</label></>}>
      {visibleSettings.length ? <table><thead><tr><th>Setting</th><th>Value</th><th>Source</th><th>Status</th><th>OFG Location</th><th>Custom Logic</th><th>Action</th></tr></thead><tbody>{visibleSettings.filter((item) => matches(`${item.display_name} ${item.description || ""} ${item.ofg_menu_path || ""} ${item.subsection || ""}`, item.category, item.status, search, category, filter) && (relevance === "all" || item.relevance_label === relevance) && (!customOnly || item.requires_custom_logic)).map((item) => <tr key={item.id}><td><strong>{item.display_name}</strong><small><span className="ofg-category-chip">{item.category}</span> · {relevanceLabel(item.relevance_label)}</small></td><td>{displayValue(item.value_json ?? item.structured_value_json)} {item.unit}</td><td>{item.source_type}<small>{item.source_machine_facts.map((fact) => fact.name).join(", ")}</small></td><td><span className={`post-status ${item.status}`}>{ofgStatus(item.status)}</span></td><td>{item.ofg_menu_path || "—"}<small>{pathLabel(item.ofg_menu_path_status)}</small></td><td>{item.requires_custom_logic ? "Required" : "No"}</td><td><Link className="button tertiary" to={`${base}/ofg-configuration/${item.id}`}>Open</Link></td></tr>)}</tbody></table> : <div className="empty-state"><h3>No applicable settings.</h3><p>Review machine type, controller, and capabilities in Machine Knowledge.</p></div>}
    </EngineeringTable>}
    {view === "ofg-configuration" && selectedSetting && <OFGDetail setting={selectedSetting} applications={applications} logic={logic} base={base} back={`${base}/ofg-configuration`} save={(payload) => act(() => api.updateOFGSetting(id, selectedSetting.id, payload))} />}

    {view === "ofg-configuration" && !selectedSetting && <details className="site-standards-context"><summary>Site Standards · {applications.length} applied</summary><SiteStandardsView standards={standards} applications={applications} busy={busy}
      create={(payload) => act(() => api.createSiteStandard(payload))}
      apply={(standardId) => act(() => api.applySiteStandard(id, { site_standard_id: standardId, status: "applied", conflict_status: "none" }))}
      conflict={(item) => act(() => api.updatePostStandard(id, item.id, { site_standard_id: item.site_standard_id, status: item.status, conflict_status: "requires_review", conflict_note: "Machine evidence and site behavior require engineering review.", reviewer: "Local Engineer", review_note: "Manual conflict recorded." }))} /></details>}
    {view === "custom-logic" && <CustomLogicView items={logic} base={base} create={(payload) => act(() => api.createCustomLogic(id, payload))} />}
    {view === "review-export" && <ReviewValidationView base={base} summary={summary} questions={questions} validations={validations} findings={findings}
      resolveQuestion={(item) => act(() => api.updatePostQuestion(id, item.id, { question_type: item.question_type, title: item.title, description: item.description, severity: item.severity, related_type: item.related_type, related_id: item.related_id, source_context: item.source_context, owner: item.owner, status: "resolved", resolution: "Resolved by engineering review." }))}
      createValidation={(payload) => act(() => api.createPostValidation(id, payload))}
      resolveFinding={(item) => act(() => api.updateValidationFinding(id, item.id, { ...item, status: "Resolved", resolution_note: "Resolved by engineer review." }))}
    />}
    {view === "history-sources" && <HistorySourcesView versions={versions} draft={draft} busy={busy} createVersion={createVersion} documents={documents.filter((document) => draft.selected_document_ids_json.includes(document.id))} machineId={machine.id} />}
    {view === "advanced" && <AdvancedView subview={parts[1]} base={base} draft={draft} summary={summary} diagnostics={diagnostics} policy={validationPolicy} />}
    {exportOpen && <div className="confirmation-backdrop"><section className="confirmation-dialog export-package-dialog" role="dialog" aria-modal="true" aria-label="Export Post Development Package"><h2>Export Post Development Package <span className="concept-help" title="The reviewed engineering handoff containing machine knowledge, OFG settings, standards, custom logic, and review status.">ⓘ</span></h2><p>This package supports post development and handoff. It is not currently a native G-POST postprocessor file.</p><h3>Package Contents</h3><ul>{["OFG Configuration Checklist", "Reviewed Machine Knowledge", "Applied Site Standards", "Custom Logic Summary", "Open Questions", "Review Summary", "Validation Records", "Sources / Evidence", "Version Metadata"].map((item) => <li key={item}>{item}</li>)}</ul><footer><button className="button secondary" onClick={() => setExportOpen(false)}>Cancel</button><a className="button secondary" href={api.postDevelopmentPackageUrl(id, "json")}>Export JSON</a><a className="button primary" href={api.postDevelopmentPackageUrl(id, "markdown")}>Export Package</a></footer></section></div>}
  </section>;
}

function matches(name: string, itemCategory: string, status: string, search: string, category: string, filter: string) {
  return (!search || `${name} ${itemCategory}`.toLowerCase().includes(search.toLowerCase())) && (category === "all" || category === itemCategory) && (filter === "all" || filter === status);
}
function Badge({ value }: { value: string }) { return <span className={`post-status ${value}`}>{pretty(value)}</span>; }

function Overview({ base, machine, summary, documents }: { base: string; draft: GPostDraft; machine: MachineProfile; summary: PostRecordSummary; documents: SourceDocument[] }) {
  const unresolvedFacts = Math.max(0, summary.machine_knowledge.total - summary.machine_knowledge.reviewed); const remainingSettings = Math.max(0, summary.ofg_configuration.total - summary.ofg_configuration.reviewed); const outstanding = summary.blockers.length + summary.open_questions.open;
  const customUnresolved = Math.max(0, summary.custom_logic.identified - summary.custom_logic.reviewed); const nextPath = summary.next_action.path === "review-validation" ? "review-export" : summary.next_action.path === "site-standards" ? "ofg-configuration" : summary.next_action.path;
  return <div className="post-record-overview"><section className="panel development-progress"><header><div><h2>Post Development Progress</h2><p>{machine.name} · {machine.controller_model || machine.controller_name}</p></div></header><Progress label="Machine Knowledge" value={`${summary.machine_knowledge.reviewed} confirmed · ${unresolvedFacts} unresolved`} />
      <Progress label="OFG Configuration" value={`${summary.ofg_configuration.reviewed} reviewed · ${remainingSettings} remaining`} />
      <Progress label="Site Standards" value={`${summary.site_standards.applied} applied`} />
      <Progress label="Custom Logic" value={`${customUnresolved} unresolved`} />
      <Progress label="Open Items" value={String(outstanding)} />
      <Progress label="Current Status" value={(overallLabels[summary.status] || pretty(summary.status)).toUpperCase()} />
      <Link className="button primary overview-next-action" to={`${base}/${nextPath}`}>{summary.next_action.label}</Link>
    </section><section className="panel needs-attention"><h2>Needs Attention</h2>{summary.blockers.length ? summary.blockers.slice(0, 5).map((item) => <Link key={`${item.type}-${item.id}`} to={`${base}/${item.type === "machine_fact" ? "machine-knowledge" : "ofg-configuration"}/${item.id}`}><strong>{item.title}</strong><span>{pretty(item.reason)}</span></Link>) : <p>No current blockers.</p>}<small>{documents.length} source document{documents.length === 1 ? "" : "s"}</small></section></div>;
}
function Progress({ label, value }: { label: string; value: string }) { return <div className="progress-row"><strong>{label}</strong><span>{value}</span></div>; }

function EngineeringTable({ title, description, search, setSearch, filter, setFilter, category, setCategory, statuses, categories, primaryAction, extraFilter, children }: { title: React.ReactNode; description: string; search: string; setSearch: (v: string) => void; filter: string; setFilter: (v: string) => void; category: string; setCategory: (v: string) => void; statuses: string[]; categories: string[]; primaryAction?: React.ReactNode; extraFilter?: React.ReactNode; children: React.ReactNode }) {
  return <section className="engineering-module"><header className="module-heading"><div><h2>{title}</h2><p>{description}</p></div>{primaryAction}</header><div className="engineering-filters"><label>Search<input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search settings" /></label><label>Category<select value={category} onChange={(e) => setCategory(e.target.value)}><option value="all">All categories</option>{categories.map((item) => <option key={item}>{item}</option>)}</select></label><label>Status<select value={filter} onChange={(e) => setFilter(e.target.value)}><option value="all">All statuses</option>{statuses.map((item) => <option key={item} value={item}>{ofgStatus(item)}</option>)}</select></label>{extraFilter}</div><div className="panel table-wrap engineering-table">{children}</div></section>;
}

function MachineFactDetail({ fact, back, save, machineId }: { fact: MachineKnowledgeFact; back: string; save: (payload: Record<string, unknown>) => void; machineId: number }) {
  const [value, setValue] = useState(displayValue(fact.value_json) === "—" ? "" : displayValue(fact.value_json)); const [status, setStatus] = useState(fact.status); const [reviewer, setReviewer] = useState(fact.reviewer || "Local Engineer");
  const payload = () => ({ category: fact.category, fact_key: fact.fact_key, name: fact.name, value_json: value || null, unit: fact.unit, status, source_document_id: fact.source_document_id, source_label: fact.source_label, source_location: fact.source_location, reviewer, review_note: fact.review_note });
  return <section className="record-detail"><Link to={back}>← Machine Knowledge</Link><header><span className="eyebrow">{fact.category}</span><h2>{fact.name}</h2><Badge value={fact.status} /></header><div className="detail-grid"><section className="panel"><h3>Reviewed Fact</h3><label>Value<input value={value} onChange={(e) => setValue(e.target.value)} /></label><label>Unit<input value={fact.unit || ""} disabled /></label><label>Status<select value={status} onChange={(e) => setStatus(e.target.value)}>{factStatuses.map((item) => <option key={item} value={item}>{pretty(item)}</option>)}</select></label><label>Reviewer<input value={reviewer} onChange={(e) => setReviewer(e.target.value)} /></label><button className="button primary" onClick={() => save({ ...payload(), status: "confirmed" })}>Confirm</button><button className="button secondary" onClick={() => save(payload())}>Save Review</button><button className="button secondary" onClick={() => save({ ...payload(), status: "needs_review" })}>Needs More Information</button></section><section className="panel"><h3>Traceability</h3><dl><div><dt>Source</dt><dd>{fact.source_label || "Manual entry"}</dd></div><div><dt>Location</dt><dd>{fact.source_location || "—"}</dd></div><div><dt>Used By</dt><dd>{fact.used_by.length ? fact.used_by.map((item) => `OFG Configuration → ${item.label}`).join(", ") : "No OFG mappings yet"}</dd></div><div><dt>Custom Logic</dt><dd>Not required</dd></div></dl><Link to={`/machine-assistant?machine=${machineId}`}>Ask Machine Assistant</Link></section></div></section>;
}

function OFGDetail({ setting, applications, logic, base, back, save }: { setting: OFGSetting; applications: PostStandardApplication[]; logic: CustomLogicItem[]; base: string; back: string; save: (payload: Record<string, unknown>) => void }) {
  const [value, setValue] = useState(displayValue(setting.value_json) === "—" ? "" : displayValue(setting.value_json)); const [status, setStatus] = useState(setting.status); const [custom, setCustom] = useState(setting.requires_custom_logic); const [notes, setNotes] = useState(setting.review_note || "");
  const [sourceType, setSourceType] = useState(setting.source_type); const [codeStatus, setCodeStatus] = useState<string>(setting.code_status || "unknown"); const [userSelected, setUserSelected] = useState(setting.user_selected);
  const payload = { category: setting.category, subsection: setting.subsection, setting_key: setting.setting_key, display_name: setting.display_name, description: setting.description, value_json: value || null, unit: setting.unit, status, source_machine_fact_ids_json: setting.source_machine_fact_ids_json, source_document_evidence_ids_json: setting.source_document_evidence_ids_json, site_standard_ids_json: setting.site_standard_ids_json, requires_custom_logic: custom, custom_logic_id: setting.custom_logic_id, ofg_menu_path: setting.ofg_menu_path, ofg_menu_path_status: setting.ofg_menu_path_status, relevance_class: setting.relevance_class, relevance_label: setting.relevance_label, is_applicable: setting.is_applicable, user_selected: userSelected, source_type: sourceType, source_reference: setting.source_reference, structured_value_json: setting.structured_value_json, code_status: setting.code_status === null ? null : codeStatus, reviewer: "Local Engineer", review_note: notes || null };
  const applied = applications.filter((item) => setting.site_standard_ids_json.includes(item.site_standard_id));
  const customLogic = logic.find((item) => item.id === setting.custom_logic_id);
  return <section className="record-detail"><Link to={back}>← OFG Configuration</Link><header><span className="eyebrow">{setting.category} · {setting.subsection}</span><h2>{setting.display_name}</h2><span className={`post-status ${setting.status}`}>{ofgStatus(setting.status)}</span></header><div className="detail-grid"><section className="panel"><h3>Configuration Requirement</h3><p>{setting.description}</p><dl><div><dt>Relevance</dt><dd>{relevanceLabel(setting.relevance_label)} · {pretty(setting.relevance_class)}</dd></div></dl><label>Value<input value={value} onChange={(e) => setValue(e.target.value)} /></label>{setting.structured_value_json != null && <StructuredOFGValue value={setting.structured_value_json} />}{setting.code_status !== null && <label>Code Status<select value={codeStatus} onChange={(e) => setCodeStatus(e.target.value)}><option value="defined">Defined</option><option value="not_available">Not Available</option><option value="not_required">Not Required</option><option value="unknown">Unknown</option></select></label>}<label>Status<select value={status} onChange={(e) => setStatus(e.target.value)}>{ofgStatuses.map((item) => <option key={item} value={item}>{ofgStatus(item)}</option>)}</select></label><label>Source Type<select value={sourceType} onChange={(e) => setSourceType(e.target.value as OFGSetting["source_type"])}>{["Machine Knowledge", "Controller Documentation", "OFG Reference", "Site Standard", "Existing Post Reference", "Engineer Entry", "Unknown"].map((item) => <option key={item}>{item}</option>)}</select></label>{setting.relevance_class === "advanced" && <label><input type="checkbox" checked={userSelected} onChange={(e) => setUserSelected(e.target.checked)} /> Explicitly applicable to this post</label>}<label>Engineer Notes<textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Record review rationale, uncertainties, or handoff notes" /></label><label><input type="checkbox" checked={custom} onChange={(e) => setCustom(e.target.checked)} /> Custom logic required</label>{custom && <aside className="custom-logic-callout"><strong>Custom Logic Required</strong><p><b>Reason:</b> {customLogic?.reason || "Requires machine/site-specific post behavior beyond the standard configuration checklist."}</p><Link className="button secondary" to={`${base}/custom-logic`}>Open Custom Logic</Link><small>Implementation may use FIL/CIMFIL; site verification is required.</small></aside>}<button className="button primary" onClick={() => save(payload)}>Save Setting</button></section><section className="panel traceability-chain"><h3>Traceability</h3><dl><div><dt>Source Type</dt><dd>{sourceType}</dd></div><div><dt>Source Reference</dt><dd>{setting.source_reference || "—"}</dd></div></dl><h3>Source Machine Facts</h3>{setting.source_machine_facts.length ? setting.source_machine_facts.map((fact) => <article key={fact.id}><strong>{fact.name}</strong><p>{displayValue(fact.value)} {setting.unit} · {fact.status === "confirmed" ? "Confirmed" : pretty(fact.status)}</p><small>Supporting Source: {fact.source || "Manual entry"} {fact.source_location || ""}</small><Link to={`${base}/machine-knowledge/${fact.id}`}>View Machine Fact</Link></article>) : <p>No Machine Knowledge source is mapped.</p>}<div className="traceability-arrow">Controller Document / Machine Knowledge / Site Standard → OFG Engineering Choice</div><h3>OFG Location</h3><p><strong>{pathLabel(setting.ofg_menu_path_status)}:</strong> {setting.ofg_menu_path || "No reference path recorded"}</p><small>This status describes the collected OFG research reference, not verification in the installed site environment.</small><h3>Custom Logic</h3><p>{custom ? "Required — review the linked custom logic record." : "Not identified for this setting."}</p></section></div>{applied.length > 0 && <section className="panel applied-standards"><h3>Site Standard Applied</h3>{applied.map((item) => <article key={item.id}><div><strong>{item.standard.name}</strong><p>{item.standard.rule}</p></div><Link className="button tertiary" to={`${base}/ofg-configuration`}>View Standard</Link>{item.conflict_status !== "none" && <aside className="conflict-callout"><strong>Conflict Requires Review</strong><p><b>Machine Knowledge:</b> {setting.source_machine_facts.map((fact) => `${fact.name}: ${displayValue(fact.value)}`).join(", ") || "No source fact"}</p><p><b>Site Standard:</b> {item.standard.rule}</p></aside>}</article>)}</section>}</section>;
}

function StructuredOFGValue({ value }: { value: unknown }) {
  if (Array.isArray(value) && value.length && typeof value[0] === "object") {
    const rows = value as Array<Record<string, unknown>>; const keys = Object.keys(rows[0]);
    return <div className="structured-ofg-value"><h4>Structured Values</h4><div className="table-wrap"><table><thead><tr>{keys.map((key) => <th key={key}>{pretty(key)}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={index}>{keys.map((key) => <td key={key}>{displayValue(row[key])}</td>)}</tr>)}</tbody></table></div></div>;
  }
  if (value && typeof value === "object") return <div className="structured-ofg-value"><h4>Structured Values</h4><dl>{Object.entries(value as Record<string, unknown>).map(([key, item]) => <div key={key}><dt>{pretty(key)}</dt><dd>{displayValue(item)}</dd></div>)}</dl></div>;
  return null;
}

function SiteStandardsView({ standards, applications, busy, create, apply, conflict }: { standards: SiteStandard[]; applications: PostStandardApplication[]; busy: boolean; create: (p: Record<string, unknown>) => void; apply: (id: number) => void; conflict: (item: PostStandardApplication) => void }) {
  const [show, setShow] = useState(false); const [name, setName] = useState(""); const [rule, setRule] = useState(""); const [scope, setScope] = useState("global"); const [validationRequirement, setValidationRequirement] = useState("");
  const applied = new Set(applications.map((item) => item.site_standard_id));
  if (!applications.length && !show) return <section className="engineering-module"><header className="module-heading"><div><h2>Site Standards <span className="concept-help" title="Shop-specific post behavior that may not appear in the machine or controller manual.">ⓘ</span></h2><p>Shop-specific behavior applied explicitly to this Post Record.</p></div><button className="button primary" onClick={() => setShow(true)}>Create Site Standard</button></header><div className="panel empty-state"><h3>No site standards applied.</h3><p>Apply a reviewed shop standard when site-specific behavior affects this post.</p></div>{standards.length > 0 && <div className="standard-grid">{standards.map((item) => <article className="panel" key={item.id}><h3>{item.name}</h3><p>{item.rule}</p><button className="button secondary" onClick={() => apply(item.id)}>Apply to Post Record</button></article>)}</div>}</section>;
  return <section className="engineering-module"><header className="module-heading"><div><h2>Site Standards</h2><p>Shop-specific behavior applied explicitly to this Post Record.</p></div><button className="button primary" onClick={() => setShow(!show)}>Create Site Standard</button></header>{show && <section className="panel inline-form"><label>Name<input value={name} onChange={(e) => setName(e.target.value)} /></label><label>Scope<select value={scope} onChange={(e) => setScope(e.target.value)}><option value="global">Global</option><option value="machine_family">Machine Family</option><option value="controller_family">Controller Family</option><option value="specific_machine">Specific Machine</option><option value="specific_post_record">Specific Post Record</option></select></label><label>Rule<textarea value={rule} onChange={(e) => setRule(e.target.value)} /></label><label>Required validation stage<select value={validationRequirement} onChange={(e) => setValidationRequirement(e.target.value)}><option value="">None</option><option>VERICUT Simulation</option><option>NC Programmer Review</option><option>Dry Run</option><option>Site Qualification</option></select></label><button className="button primary" disabled={!name || !rule || busy} onClick={() => { create({ name, description: null, scope, applicable_machine_types_json: [], applicable_controller_families_json: [], applicable_machine_ids_json: [], category: "Program Behavior", rule, validation_requirements_json: validationRequirement ? [validationRequirement] : [], source: "Local engineering standard", status: "needs_review", reviewer: null, version: 1, effective_date: null, notes: null }); setShow(false); }}>Save Standard</button></section>}<div className="standard-grid">{applications.map((item) => <article className="panel" key={item.id}><header><h3>{item.standard.name}</h3><Badge value={item.status} /></header><p>{item.standard.rule}</p><dl><div><dt>Scope</dt><dd>{pretty(item.standard.scope)}</dd></div><div><dt>Required Validation</dt><dd>{item.standard.validation_requirements_json?.join(", ") || "No additional gate"}</dd></div><div><dt>Conflict</dt><dd>{item.conflict_status === "none" ? "None recorded" : "CONFLICT / SITE OVERRIDE REQUIRES REVIEW"}</dd></div></dl>{item.conflict_note && <p className="form-error">{item.conflict_note}</p>}<button className="button secondary" onClick={() => conflict(item)}>Record Conflict</button></article>)}{standards.filter((item) => !applied.has(item.id)).map((item) => <article className="panel" key={item.id}><h3>{item.name}</h3><p>{item.rule}</p><small>{pretty(item.scope)}</small><button className="button secondary" onClick={() => apply(item.id)}>Apply to Post Record</button></article>)}</div></section>;
}

function CustomLogicView({ items, base, create }: { items: CustomLogicItem[]; base: string; create: (p: Record<string, unknown>) => void }) {
  const [show, setShow] = useState(false); const [name, setName] = useState(""); const [reason, setReason] = useState("");
  if (!items.length && !show) return <section className="engineering-module"><header className="module-heading"><div><h2>Custom Logic <span className="concept-help" title="Machine/site-specific behavior that may require post customization beyond the standard OFG checklist.">ⓘ</span></h2><p>Track why standard OFG configuration is not sufficient.</p></div><button className="button primary" onClick={() => setShow(true)}>Identify Custom Logic</button></header><div className="panel empty-state"><h3>No custom logic identified.</h3><p>This may be normal for a simple post.</p></div></section>;
  return <section className="engineering-module"><header className="module-heading"><div><h2>Custom Logic</h2><p>Track behavior that may require post customization beyond the standard OFG checklist. FIL/CIMFIL is only a potential implementation until verified locally.</p></div><button className="button primary" onClick={() => setShow(!show)}>Identify Custom Logic</button></header>{show && <section className="panel inline-form"><label>Behavior<input value={name} onChange={(e) => setName(e.target.value)} /></label><label>Why is customization needed?<textarea value={reason} onChange={(e) => setReason(e.target.value)} /></label><button className="button primary" onClick={() => { create({ name, category: "Unclassified", reason, implementation_type: "Potential FIL/CIMFIL customization", status: "needs_review", evidence_ids_json: [], site_standard_ids_json: [], source_format: "Site verification required", source_reference: null, reviewer: null, review_note: null }); setShow(false); }}>Save Item</button></section>}<div className="panel table-wrap custom-logic-tracker"><table><thead><tr><th>Behavior</th><th>Reason</th><th>Possible Implementation</th><th>Status</th><th>Action</th></tr></thead><tbody>{items.map((item) => <tr key={item.id}><td><strong>{item.name}</strong><small>{item.category}</small></td><td>{item.reason}</td><td>{item.implementation_type === "FIL / CIMFIL" ? "Potential FIL/CIMFIL customization — verification required" : item.implementation_type}</td><td><Badge value={item.status} /></td><td><details><summary>Open</summary><dl><div><dt>Desired machine-level result</dt><dd>{item.reason}</dd></div><div><dt>Source evidence</dt><dd>{item.evidence_ids_json.length} reference{item.evidence_ids_json.length === 1 ? "" : "s"}</dd></div><div><dt>Site standard</dt><dd>{item.site_standard_ids_json.length ? `${item.site_standard_ids_json.length} linked` : "None linked"}</dd></div><div><dt>Runtime trigger</dt><dd>Not yet verified</dd></div><div><dt>Implementation type</dt><dd>{item.implementation_type}</dd></div><div><dt>Review state</dt><dd>{pretty(item.status)}</dd></div><div><dt>Notes</dt><dd>{item.review_note || "No engineer notes"}</dd></div></dl><Link className="button tertiary" to={`${base}/advanced/fil-editor?item=${item.id}`}>Open FIL Workspace</Link></details></td></tr>)}</tbody></table></div></section>;
}

function ReviewValidationView({ base, summary, questions, validations, findings, resolveQuestion, createValidation, resolveFinding }: {
  base: string; summary: PostRecordSummary; questions: PostOpenQuestion[]; validations: PostValidationRecord[]; findings: ValidationFinding[];
  resolveQuestion: (question: PostOpenQuestion) => void; createValidation: (payload: Record<string, unknown>) => void; resolveFinding: (finding: ValidationFinding) => void;
}) {
  const recordId = Number(base.split("/").pop());
  const types = ["G-POST Compilation", "Controlled Test Post", "VERICUT Simulation", "NC Programmer Review", "Dry Run"];
  const [showForm, setShowForm] = useState(false); const [type, setType] = useState(types[0]); const [result, setResult] = useState("PASS_WITH_FINDINGS");
  const [performedBy, setPerformedBy] = useState("Local Engineer"); const [performedAt, setPerformedAt] = useState(""); const [notes, setNotes] = useState(""); const [reference, setReference] = useState("");
  const latest = (kinds: string[]) => validations.find((item) => kinds.includes(item.validation_type));
  const outstandingQuestions = questions.filter((item) => item.status !== "resolved"); const outstandingFindings = findings.filter((item) => item.status !== "Resolved");
  const blockerPath = (type: string, id: number) => type === "machine_fact" ? `${base}/machine-knowledge/${id}` : type === "ofg_setting" ? `${base}/ofg-configuration/${id}` : `${base}/site-standards`;
  return <section className="review-validation"><header className="module-heading"><div><span className="eyebrow">Post Development Review</span><h2>Review &amp; Export</h2><p>Resolve remaining engineering attention before handing the Post Development Package to the local G-POST / Option File Generator workflow.</p></div><button className="button secondary" onClick={() => setShowForm(!showForm)}>Add Validation Record</button></header>
    <section className="panel v1-review-summary"><h3>Completion</h3><div className="review-completion-grid">
      <Progress label="Machine Knowledge" value={`${summary.machine_knowledge.reviewed}/${summary.machine_knowledge.total}`} /><Progress label="OFG Configuration" value={`${summary.ofg_configuration.reviewed}/${summary.ofg_configuration.total}`} /><Progress label="Site Standards" value={`${summary.site_standards.applied} applied`} /><Progress label="Custom Logic" value={`${summary.custom_logic.reviewed}/${summary.custom_logic.identified}`} /><Progress label="Open Questions" value={String(summary.open_questions.open)} /><Progress label="Validation" value={validations.length ? "Recorded" : "Not Recorded"} />
    </div></section>
    <section className="panel"><h3>Outstanding Items</h3>{!summary.blockers.length && !outstandingQuestions.length && !outstandingFindings.length ? <p>No outstanding items.</p> : <div className="table-wrap"><table><thead><tr><th>Type</th><th>Item</th><th>Reason</th><th>Action</th></tr></thead><tbody>
      {summary.blockers.map((item) => <tr key={`blocker-${item.type}-${item.id}`}><td>{item.type === "machine_fact" ? "Machine Knowledge" : item.type === "ofg_setting" ? "OFG" : "Site Standard"}</td><td>{item.title}</td><td>{pretty(item.reason)}</td><td><Link className="button tertiary" to={blockerPath(item.type, item.id)}>{item.type === "ofg_setting" ? "Open" : "Resolve"}</Link></td></tr>)}
      {outstandingQuestions.map((item) => <tr key={`question-${item.id}`}><td>Open Question</td><td>{item.title}</td><td>{item.description || pretty(item.severity)}</td><td><button className="button tertiary" onClick={() => resolveQuestion(item)}>Resolve</button></td></tr>)}
      {outstandingFindings.map((item) => <tr key={`finding-${item.id}`}><td>Review Finding</td><td>{item.title}</td><td>{item.description || pretty(item.severity)}</td><td><button className="button tertiary" onClick={() => resolveFinding(item)}>Resolve</button></td></tr>)}
    </tbody></table></div>}</section>
    <section className="panel"><header className="module-heading"><div><h3>Validation</h3><p>Manual records only; this app does not run external tools.</p></div></header><div className="validation-stage-grid">
      <Progress label="G-POST Test" value={latest(["Controlled Test Post", "G-POST Compilation"])?.result ? pretty(latest(["Controlled Test Post", "G-POST Compilation"])!.result) : "Not Recorded"} /><Progress label="VERICUT" value={latest(["VERICUT Simulation"])?.result ? pretty(latest(["VERICUT Simulation"])!.result) : "Not Recorded"} /><Progress label="Engineer Review" value={latest(["NC Programmer Review"])?.result ? pretty(latest(["NC Programmer Review"])!.result) : "Not Recorded"} />
    </div>{showForm && <div className="inline-form"><label>Type<select value={type} onChange={(event) => setType(event.target.value)}>{types.map((item) => <option key={item}>{item}</option>)}</select></label><label>Result<select value={result} onChange={(event) => setResult(event.target.value)}>{["PASS", "PASS_WITH_FINDINGS", "FAIL", "NEEDS_REVIEW", "BLOCKED", "NOT_APPLICABLE"].map((item) => <option key={item} value={item}>{pretty(item)}</option>)}</select></label><label>Performed By<input value={performedBy} onChange={(event) => setPerformedBy(event.target.value)} /></label><label>Date<input type="date" value={performedAt} onChange={(event) => setPerformedAt(event.target.value)} /></label><label>Notes<textarea value={notes} onChange={(event) => setNotes(event.target.value)} /></label><label>Reference<input value={reference} onChange={(event) => setReference(event.target.value)} /></label><button className="button primary" onClick={() => { createValidation({ post_version_id: null, validation_type: type, name: `${type} record`, performed_by: performedBy, performed_at: performedAt || null, environment: "Approved engineering environment", result, notes, attachment_reference: null, external_tool: type.includes("VERICUT") ? "VERICUT" : null, external_reference: reference || null, test_program_name: null, findings_count: 0, blocking_findings_count: 0, references_json: [], ai_used: false }); setShowForm(false); }}>Save Validation</button></div>}</section>
    <section className="panel package-finish-line"><header><div><span className="eyebrow">Finish line</span><h3>Post Development Package</h3></div></header><p>This package supports engineering development and handoff. It is not currently a compiled or native G-POST postprocessor file.</p><ul>{["Machine Summary", "Confirmed Machine Knowledge", "OFG Configuration Checklist", "Applied Site Standards", "Custom Logic Summary", "Reviewed FIL source if available and verified", "Open Questions", "Review Summary", "Validation Records", "Sources", "Version Metadata"].map((item) => <li key={item}>{item}</li>)}</ul><div className="package-format-actions"><a className="button primary" href={api.postDevelopmentPackageUrl(recordId, "markdown")}>Engineering Report</a><a className="button secondary" href={api.postDevelopmentPackageUrl(recordId, "csv")}>OFG Checklist CSV</a><a className="button tertiary" href={api.postDevelopmentPackageUrl(recordId, "json")}>R&amp;D JSON</a></div></section>
  </section>;
}

function HistorySourcesView({ versions, draft, busy, createVersion, documents, machineId }: { versions: GPostDraft[]; draft: GPostDraft; busy: boolean; createVersion: () => Promise<void>; documents: SourceDocument[]; machineId: number }) {
  return <section className="history-sources"><header><h2>History &amp; Sources</h2><p>Version lineage and the engineering source documents selected for this Post Record.</p></header>{versions.length <= 1 ? <VersionsEmpty busy={busy} createVersion={createVersion} /> : <VersionsView versions={versions} draft={draft} busy={busy} createVersion={createVersion} />}<SourcesView documents={documents} machineId={machineId} /></section>;
}

function VersionsEmpty({ busy, createVersion }: { busy: boolean; createVersion: () => Promise<void> }) {
  return <section className="engineering-module"><header className="module-heading"><div><h2>Version History</h2><p>Complete read-only snapshots of one Post Development Package lineage.</p></div><button className="button primary" disabled={busy} onClick={() => void createVersion()}>Create Version</button></header><div className="panel empty-state"><h3>No prior versions yet.</h3><p>Create a version when the current Post Development Package reaches a meaningful review point.</p></div></section>;
}

function VersionsView({ versions, draft, busy, createVersion }: { versions: GPostDraft[]; draft: GPostDraft; busy: boolean; createVersion: () => Promise<void> }) { const [comparison, setComparison] = useState<Record<string, unknown> | null>(null); return <section className="engineering-module"><header className="module-heading"><div><h2>Version History</h2><p>Complete read-only snapshots of one Post Development Package lineage.</p></div><button className="button primary" disabled={busy} onClick={() => void createVersion()}>Create Version</button></header>{comparison && <section className="panel"><h3>Package Comparison</h3><pre>{JSON.stringify(comparison, null, 2)}</pre></section>}<div className="panel table-wrap"><table><thead><tr><th>Version</th><th>Status</th><th>Created</th><th>Package</th><th>Action</th></tr></thead><tbody>{versions.map((item) => <tr key={item.id}><td>v{item.version}</td><td>{item.id === draft.id ? "Current" : "Historical · Read-only"}</td><td>{new Date(item.created_at).toLocaleDateString()}</td><td>Machine Knowledge · OFG · Standards · Logic · Questions · Validation</td><td><Link className="button tertiary" to={`/gpost/${item.id}`}>Open</Link>{item.id !== draft.id && <button className="button tertiary" onClick={() => void api.comparePostRecords(draft.id, item.id).then(setComparison)}>Compare with Current</button>}</td></tr>)}</tbody></table></div></section>; }
function SourcesView({ documents, machineId }: { documents: SourceDocument[]; machineId: number }) { return <section className="engineering-module"><header><h2>Source Documents</h2><p>Machine-level engineering references selected for this Post Record.</p></header><div className="source-list">{documents.map((item) => <article className="panel source-row" key={item.id}><div><strong>{item.title}</strong><small>{pretty(item.document_type)}</small></div><div><span>Extraction Status</span><strong>{pretty(item.processing_status)}</strong></div><Link className="button tertiary" to={`/documents/${item.id}`}>Open</Link></article>)}</div><Link className="button secondary" to={`/documents?machine=${machineId}`}>Manage Documents</Link></section>; }
function AdvancedView({ subview, base, draft, summary, diagnostics, policy }: { subview?: string; base: string; draft: GPostDraft; summary: PostRecordSummary; diagnostics: GPostDiagnostic[]; policy: ValidationPolicy | null }) {
  if (subview === "legacy-ai") return <section className="panel"><h2>Legacy AI Experiments</h2><p>Phase 11 section-drafting functionality is retained for compatibility and research. It is not the primary Post Record workflow.</p><Link className="button secondary" to={`${base}/advanced/legacy-ai-workspace/builder`}>Open Legacy Component Workspace</Link></section>;
  if (subview === "fil-editor") return <section className="panel"><h2>FIL / CIMFIL Editor</h2><p>Specialist custom-logic workspace. No new AI generation is enabled in this milestone.</p><dl><div><dt>Expected source format</dt><dd>Site verification required</dd></div><div><dt>Native extension/naming</dt><dd>Not verified</dd></div></dl><p>Use a Custom Logic item to record evidence, status, and implementation references before editing source.</p></section>;
  return <section className="panel technical-details"><h2>Technical Details</h2><dl><div><dt>Post Record ID</dt><dd>{draft.id}</dd></div><div><dt>Machine Configuration Revision</dt><dd>#{draft.machine_profile_revision_id}</dd></div><div><dt>Validation Policy</dt><dd>{policy?.name || "Not configured"}</dd></div><div><dt>Local Diagnostic Records</dt><dd>{diagnostics.length}</dd></div><div><dt>Native File Generation</dt><dd>Not verified</dd></div></dl><p>{summary.native_gpost_integration.explanation}</p>{researchToolsEnabled && <Link className="button secondary" to="/research-tools">Open Research Tools</Link>}</section>;
}
